-- Resolution of the power type that the Built In POINT condition reads (combo points, holy power, chi, soul shards and
-- so on) for a unit: which Enum.PowerType value applies to the unit's class on this client edition, or `nil, reason`
-- when it is unknown or unreadable. Owns that lookup only; the value itself is read by Platform/points.lua. Every game
-- value goes through `platform:CanReadValue` (restricted clients hide secret values). Loaded from RotationMaster.toc
-- after Core/level_conditions.lua. The block at the end is generated by tools/generate_builtin_sources.py: the
-- functions and locals it exposes are recorded Built In helpers whose exact text saved custom conditions bind to, so
-- none of them may be edited.

local _, addon = ...
local playerClassCacheKey = {}

-- ============================================================================
-- Unit identity and the original resource lookup
-- ============================================================================

-- Reads the identity facts the POINT conditions need for a unit: whether it exists and its class.
-- @param self table  The addon, whose Platform and longtermCache are used.
-- @param unit string  The unit token to identify.
-- @param key table  The private key under which the player's class is kept in the long-term cache.
-- @return table|nil  The identity record ({ exists = boolean, class = string, ... }); nil when unavailable.
-- @return string|nil  The reason code when the first return is nil; nil otherwise.
--
-- This whole identity gate is cached once per pass, independently of whether its first query promotes a successful
-- player class to the longterm cache.
local function pointIdentity(self, unit, key)
    local platform=self.Platform
    local nativeClass=UnitClass
    local longterm=self.longtermCache
    if not platform:CanReadValue(longterm) or type(longterm)~='table' then longterm=nil end
    local class
    if unit=='player' and longterm and platform:CanReadValue(nativeClass) and type(nativeClass)=='function' then
        local entry=rawget(longterm,key)
        if platform:CanReadValue(entry) and type(entry)=='table' then
            local api,candidate=rawget(entry,'api'),rawget(entry,'class')
            if platform:CanReadValue(api) and api==nativeClass and platform:CanReadValue(candidate) and type(candidate)=='string' and candidate~='' then class=candidate end
        end
    end
    local record,reason=platform:GetUnitPointIdentityObservation(unit,class==nil)
    if not record then return nil,reason end
    if not record.exists then return record end
    if class then record.class=class
    elseif unit=='player' and longterm and type(nativeClass)=='function' and nativeClass==UnitClass then
        rawset(longterm,key,{api=nativeClass,class=record.class})
    end
    return record
end

-- Finds the Enum.PowerType the original POINT condition reads for a unit's class (probe policy only).
-- @param unit string  The unit token (non-empty).
-- @param cache table|nil  The evaluation-pass cache.
-- @return number|boolean|nil  The Enum.PowerType number for the unit's class; false when the unit does not exist; nil
--   when unavailable.
-- @return string|nil  The reason code when the first return is nil; nil otherwise.
--
-- Original lookup, kept unchanged for saved Built In POINT copies that predate V2.
function addon:GetConditionPointResource(unit, cache)
    local platform=self.Platform
    if platform:GetCombatDataPolicy()~='probe' then return nil,'unsupported-policy' end
    if not platform:CanReadValue(unit) then return nil,'restricted-value' end
    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end
    local record,reason=addon.Functions.cache.getCached(cache,pointIdentity,self,unit,playerClassCacheKey)
    if not record then return nil,reason end
    if not record.exists then return false end
    local points=self.points
    if not platform:CanReadValue(points) then return nil,'restricted-value' end
    if type(points)~='table' then return nil,'invalid-point-resource-map' end
    local ok,selected=pcall(function() return points[record.class] end)
    if not ok then return nil,'api-error' end
    if not platform:CanReadValue(selected) then return nil,'restricted-value' end
    if selected==nil or selected==false then
        local enum=Enum
        if not platform:CanReadValue(enum) then return nil,'restricted-value' end
        if type(enum)~='table' then return nil,'point-resource-unavailable' end
        local typesOK,types=pcall(function() return enum.PowerType end)
        if not typesOK then return nil,'api-error' end
        if not platform:CanReadValue(types) then return nil,'restricted-value' end
        if type(types)~='table' then return nil,'point-resource-unavailable' end
        local fallbackOK,fallback=pcall(function() return types.ComboPoints end)
        if not fallbackOK then return nil,'api-error' end
        selected=fallback
        if not platform:CanReadValue(selected) then return nil,'restricted-value' end
    end
    if selected==nil then return nil,'point-resource-unavailable' end
    if type(selected)~='number' or selected~=selected or selected<0 or selected==math.huge or selected%1~=0 then return nil,'invalid-point-resource' end
    return selected
end

-- ============================================================================
-- Trusted-load enum capture and edition maps
-- ============================================================================

-- Optional trusted-load capability for the explicitly versioned TBC policy.
-- An inherited or subsequently replaced enum remains on the original transport.
local pointComboTypes, pointComboValue

do
    local platform = addon.Platform
    local enum = Enum

    if platform:CanReadValue(enum) and (not canaccessvalue or canaccessvalue(enum)) and type(enum) == 'table' then
        local types = rawget(enum, 'PowerType')

        if
            platform:CanReadValue(types) and (not canaccessvalue or canaccessvalue(types)) and type(types) == 'table'
        then
            pointComboTypes = types
            pointComboValue = rawget(types, 'ComboPoints')
        end
    end
end

-- Era and progression read only a resource the client's expansion, the class
-- and (Mists of Pandaria) the player's specialization really have. Anything
-- else is unavailable, never a Combo Points read that answers a confident 0.
-- Values are Enum.PowerType NAMES, resolved at read time; a table is keyed by
-- the specialization INDEX Blizzard's own resource bars test (SPEC_WARLOCK_*
-- 1/2/3, SPEC_PRIEST_SHADOW 3). Sources, Gethe/wow-ui-source classic
-- 45eb466ddb (5.5.4.70531), Blizzard_UnitFrame/Mists: PaladinPowerBar (Holy
-- Power, every Paladin), MonkHarmonyBar (Chi, every Monk), PriestBar (Shadow
-- Orbs, Shadow only), ShardBar (Soul Shards / Demonic Fury / Burning Embers
-- by Warlock specialization). Not mapped, on purpose:
--   Mage: Arcane Charges are a player aura before Legion (DEBUFF_STACKS 36032).
--   Death Knight: classic runes are typed; RUNE / RUNE_COOLDOWN read them.
--   Balance Eclipse: a signed -100..100 power with a direction
--   (GetEclipseDirection); POINT's negative value already means "deficit from
--   maximum", so it cannot express Eclipse. Druids read Combo Points in every
--   specialization, real (0 outside Cat Form) as on Retail.
--   Era Warlock and Mage: 1.15 has neither power (shards are bag items:
--   CARRYING 6265; SoD Arcane Blast stacks are an aura).
-- Burning Embers are reported in embers with their fraction by the power
-- observer (Platform/points.lua), so 3.5 is a valid threshold.
-- Wrath (2) has only combo points; Cataclysm (3) adds Holy Power and Soul
-- Shards for every specialization. Another progression expansion has no map
-- until it is researched.
local editionPointPowers = {
    era = { ROGUE = 'ComboPoints', DRUID = 'ComboPoints' },
    progression = {
        [2] = { ROGUE = 'ComboPoints', DRUID = 'ComboPoints' },
        [3] = { ROGUE = 'ComboPoints', DRUID = 'ComboPoints', PALADIN = 'HolyPower', WARLOCK = 'SoulShards' },
        [4] = {
            ROGUE = 'ComboPoints',
            DRUID = 'ComboPoints',
            PALADIN = 'HolyPower',
            MONK = 'Chi',
            PRIEST = { [3] = 'ShadowOrbs' },
            WARLOCK = { 'SoulShards', 'DemonicFury', 'BurningEmbers' },
        },
    },
}

-- Era and progression lookup: picks the power for the client edition, the unit's class and (for specialization tables)
-- the player's specialization index.
-- @param platform table  The Platform adapter.
-- @param info table  The client info (family, expansion) from platform:GetClientInfo().
-- @param unit string  The unit token; a specialization table only resolves for 'player'.
-- @param class string  The unit's class token.
-- @param cache table|nil  The evaluation-pass cache.
-- @return number|nil  The Enum.PowerType number; nil when unavailable.
-- @return string|nil  The reason code when the first return is nil; nil otherwise.
-- @return string|nil  The transport name, always 'power' when a number is returned; nil otherwise.
local function editionPointResource(platform, info, unit, class, cache)
    local family=info.family
    local map=editionPointPowers[family]
    if family=='progression' then
        local expansion=info.expansion
        if not platform:CanReadValue(expansion) then return nil,'restricted-value' end
        if type(expansion)~='number' then return nil,'unsupported-point-expansion' end
        map=map[expansion]
        if map==nil then return nil,'unsupported-point-expansion' end
    end
    local name=map[class]
    if type(name)=='table' then
        -- Only the player's own specialization is readable.
        if unit~='player' then return nil,'point-specialization-unavailable' end
        local spec,why=addon.Functions.cache.getCached(cache,platform.GetPlayerSpecializationIndex,platform)
        if spec==nil then return nil,why end
        name=name[spec]
    end
    if name==nil then return nil,'point-resource-unavailable' end
    local enum=Enum
    if not platform:CanReadValue(enum) then return nil,'restricted-value' end
    if type(enum)~='table' then return nil,'point-resource-unavailable' end
    local types=rawget(enum,'PowerType')
    if not platform:CanReadValue(types) then return nil,'restricted-value' end
    if type(types)~='table' then return nil,'point-resource-unavailable' end
    local selected=rawget(types,name)
    if not platform:CanReadValue(selected) then return nil,'restricted-value' end
    if selected==nil then return nil,'point-resource-unavailable' end
    if type(selected)~='number' or selected~=selected or selected<0 or selected==math.huge or selected%1~=0 then return nil,'invalid-point-resource' end
    return selected,nil,'power'
end

-- ============================================================================
-- Resource lookup V2
-- ============================================================================

-- Finds the Enum.PowerType the POINT condition reads for a unit, and the transport to read it with.
-- @param unit string  The unit token (non-empty).
-- @param cache table|nil  The evaluation-pass cache.
-- @return number|boolean|nil  The Enum.PowerType number; false when the unit does not exist; nil when unavailable.
-- @return string|nil  The reason code when the first return is nil; nil otherwise.
-- @return string|nil  The transport: 'power', or 'target-combo' for the player's combo points on the TBC client; nil
--   when the first return is not a number.
--
-- New Built In POINT copies may opt into the player/target transport; old sources keep the API above. Under the
-- restricted policy (Retail, Forever) only a power type Blizzard flags never secret is selected (Platform/points.lua);
-- its reads stay guarded. Era and progression select per edition and specialization (above).
function addon:GetConditionPointResourceV2(unit, cache)
    local platform=self.Platform
    local info=platform:GetClientInfo()
    local policy=info.combatDataPolicy
    if policy~='probe' and policy~='restricted' then return nil,'unsupported-policy' end
    if not platform:CanReadValue(unit) then return nil,'restricted-value' end
    if type(unit)~='string' or unit=='' then return nil,'invalid-unit' end
    local record,reason=addon.Functions.cache.getCached(cache,pointIdentity,self,unit,playerClassCacheKey)
    if not record then return nil,reason end
    if not record.exists then return false end
    local family=info.family
    if policy=='probe' and (family=='era' or family=='progression') then return editionPointResource(platform,info,unit,record.class,cache) end
    local points=self.points
    if not platform:CanReadValue(points) then return nil,'restricted-value' end
    if type(points)~='table' then return nil,'invalid-point-resource-map' end
    local fallbackEnum,fallbackTypes
    local ok,selected=pcall(function() return points[record.class] end)
    if not ok then return nil,'api-error' end
    if not platform:CanReadValue(selected) then return nil,'restricted-value' end
    if selected==nil or selected==false then
        local enum=Enum
        if not platform:CanReadValue(enum) then return nil,'restricted-value' end
        if type(enum)~='table' then return nil,'point-resource-unavailable' end
        local typesOK,types=pcall(function() return enum.PowerType end)
        if not typesOK then return nil,'api-error' end
        if not platform:CanReadValue(types) then return nil,'restricted-value' end
        if type(types)~='table' then return nil,'point-resource-unavailable' end
        local fallbackOK,fallback=pcall(function() return types.ComboPoints end)
        if not fallbackOK then return nil,'api-error' end
        selected=fallback
        if not platform:CanReadValue(selected) then return nil,'restricted-value' end
        fallbackEnum,fallbackTypes=enum,types
    end
    if selected==nil then return nil,'point-resource-unavailable' end
    if type(selected)~='number' or selected~=selected or selected<0 or selected==math.huge or selected%1~=0 then return nil,'invalid-point-resource' end
    if policy=='restricted' and not platform:IsNeverSecretPointPower(selected) then return nil,'unsupported-policy' end
    local transport='power'
    if unit=='player' and fallbackTypes then
        local rawTypes,rawCombo=rawget(fallbackEnum,'PowerType'),rawget(fallbackTypes,'ComboPoints')
        if platform:CanReadValue(pointComboTypes) and (not canaccessvalue or canaccessvalue(pointComboTypes))
            and platform:CanReadValue(rawTypes) and (not canaccessvalue or canaccessvalue(rawTypes))
            and rawequal(fallbackTypes,pointComboTypes) and rawequal(rawTypes,fallbackTypes)
            and platform:CanReadValue(rawCombo) and (not canaccessvalue or canaccessvalue(rawCombo)) and rawCombo==selected
            and platform:CanReadValue(pointComboValue) and (not canaccessvalue or canaccessvalue(pointComboValue))
            and pointComboValue==selected then
            local family
            if platform:CanReadValue(info) and type(info)=='table' then family=rawget(info,'family') end
            if platform:CanReadValue(family) and (not canaccessvalue or canaccessvalue(family)) and family=='tbc' then transport='target-combo' end
        end
    end
    return selected,nil,transport
end

